import{_ as t,o,c as r,a2 as n}from"./chunks/framework.Cz0TtJv6.js";const p=JSON.parse('{"title":"Strategy reference","description":"The full DLMM Bot rulebook — pool gates, token vetting, scoring, entry shape, the P0–P5 exit ladder, follow mode, and blacklist rules.","frontmatter":{"title":"Strategy reference","description":"The full DLMM Bot rulebook — pool gates, token vetting, scoring, entry shape, the P0–P5 exit ladder, follow mode, and blacklist rules."},"headers":[],"relativePath":"strategy.md","filePath":"strategy.md","lastUpdated":1786732488000}'),a={name:"strategy.md"};function s(i,e,l,d,h,g){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="strategy-reference" tabindex="-1">Strategy reference <a class="header-anchor" href="#strategy-reference" aria-label="Permalink to &quot;Strategy reference&quot;">​</a></h1><p>This page mirrors <a href="https://github.com/CryptoGnome/dlmmbot/blob/main/STRATEGY.md" target="_blank" rel="noreferrer">STRATEGY.md</a>, the repo&#39;s live spec, in plain language. Values shown are the <strong>current shipped defaults from <code>config.toml</code></strong> — several were deliberately tightened after live book review, so where the spec&#39;s original bracketed default differs, this page shows what actually runs. Everything here is hot-reloadable via <a href="./configuration">Settings / config.toml</a>.</p><p>Philosophy: <strong>capital preservation first.</strong> One-sided SOL bid-ask below price as the default entry, mechanical exits instead of conviction-holding, PnL denominated in SOL. Wherever a human would &quot;ask the group,&quot; the bot is strictly more defensive.</p><h2 id="_1-scanning" tabindex="-1">1. Scanning <a class="header-anchor" href="#_1-scanning" aria-label="Permalink to &quot;1. Scanning&quot;">​</a></h2><p>Runs every <strong>60s</strong>:</p><ol><li><strong>Pool sweep</strong> — <code>GET dlmm.datapi.meteora.ag/pools</code>, non-blacklisted pools with TVL &gt; $5,000, sorted by 30-minute fee/TVL, first <strong>3</strong> pages.</li><li><strong>Dedupe to canonical token</strong> — group pools by token mint. If multiple tokens share a symbol (copycats), only the one with the highest 24h volume is considered; the rest are ignored for <strong>24h</strong>.</li><li><strong>Best pool per token</strong> — highest <code>fee_tvl_ratio_24h</code> among that token&#39;s pools that pass the pool gates. One pool per token.</li><li>Output: scored candidates → vetting → entry queue (best score first, ties broken by younger pool).</li></ol><p>Optional discovery enrichment: GMGN trending and smart-money feeds (needs <code>GMGN_API_KEY</code>; auto-off without one — <a href="./api-keys#gmgn-api-key-gmgn_api_key-optional">how to get a key</a>). These only add <strong>score bonuses</strong> (capped at +10 total) — never a substitute for vetting. Calls are serialized and paced to stay under GMGN’s rate limits; on 429 the bot cools down until reset and keeps scanning without GMGN until then.</p><h2 id="_2-pool-gates-hard" tabindex="-1">2. Pool gates (hard) <a class="header-anchor" href="#_2-pool-gates-hard" aria-label="Permalink to &quot;2. Pool gates (hard)&quot;">​</a></h2><p>A candidate pool must pass <strong>every</strong> gate:</p><table tabindex="0"><thead><tr><th>Gate</th><th>Current default</th><th>Why</th></tr></thead><tbody><tr><td>TVL</td><td>≥ $5,000 and ≤ $2,000,000</td><td>Below: no routing, arb-only. Above: fees too diluted for meme mode</td></tr><tr><td>Market cap</td><td>≥ $100,000 ($100–200k routes to the <strong>micro</strong> sleeve)</td><td>Hard floor</td></tr><tr><td>Fee/TVL 24h (or lifetime if pool &lt; 24h old)</td><td>≥ 20%/day</td><td>The meme-pool heat threshold</td></tr><tr><td>Fee/TVL 30m, annualized to daily</td><td>≥ 10%/day</td><td>Catches pools that <em>were</em> hot but died</td></tr><tr><td>Volume 30m</td><td>≥ $25,000</td><td>Fees need flow <em>now</em>, not this morning</td></tr><tr><td>Volume trend <code>vol_1h / (vol_24h/24)</code></td><td>≥ 0.8</td><td>Current hour at least ~80% of the daily average — not in freefall</td></tr><tr><td>Base fee</td><td>0.2%–5%</td><td>&gt; 5% = arb-only pools</td></tr><tr><td>Bin step</td><td>≥ 80 for tokens &lt; 7 days old</td><td>Wide coverage with fewer bins</td></tr><tr><td>Fee collection</td><td><code>prefer_quote</code> — quote-only (SOL) pools get a score bonus; both-token pools stay eligible</td><td>Quote-only pools pay fees pre-converted to SOL. Hard modes <code>quote_only</code> / <code>both_only</code> / <code>any</code> exist in config</td></tr><tr><td>Quote token</td><td>SOL required</td><td>Accumulate-SOL thesis; stable/USDC pairs are out of scope</td></tr><tr><td>Pool price vs Jupiter quote</td><td>divergence ≤ 2%</td><td>The oracle-glitch / empty-pool trap</td></tr><tr><td>Pool share</td><td>our position ≤ 20% of pool TVL</td><td>Otherwise <em>we&#39;d be</em> the exit liquidity</td></tr></tbody></table><h2 id="_3-token-vetting-gates-hard" tabindex="-1">3. Token vetting gates (hard) <a class="header-anchor" href="#_3-token-vetting-gates-hard" aria-label="Permalink to &quot;3. Token vetting gates (hard)&quot;">​</a></h2><p>Computed <strong>fresh at entry time</strong> from RPC + the RugCheck free API:</p><ul><li>Mint authority revoked, freeze authority revoked.</li><li>Token program: SPL Token, or Token-2022 with <strong>no</strong> extensions beyond metadata (no transfer fees or hooks).</li><li>Single holder ≤ <strong>15%</strong> of supply; top-10 holders ≤ <strong>40%</strong> — both excluding labeled pool vaults, lockers, and burn addresses.</li><li>Insider/funding clusters ≤ <strong>10%</strong> of supply (same-funder wallet clustering + launch-slot snipers).</li><li>Creator has <strong>zero</strong> rugged tokens in our DB or RugCheck&#39;s <code>creatorTokens</code>. One strike = permanent creator blacklist.</li><li>RugCheck <code>score_normalised</code> &lt; <strong>41</strong> (their &quot;Danger&quot; line) — used as a <strong>veto only</strong>, never as approval.</li><li>Token age ≥ <strong>45 min</strong> (survive the instant-rug window) and ≤ <strong>14 days</strong> in meme mode. Age is the mint&#39;s age via RugCheck, not the pool&#39;s.</li><li>Not on our blacklist (§8 below).</li></ul><p>Each vetting check has a master on/off switch in Settings (age min/max, insider gate, holder gate, RugCheck veto, creator-rug gate, GMGN honeypot/sell-tax gate). Off = skip that hard fail; thresholds still apply when on.</p><h2 id="_4-timing-filter-soft-—-feeds-the-score" tabindex="-1">4. Timing filter (soft — feeds the score) <a class="header-anchor" href="#_4-timing-filter-soft-—-feeds-the-score" aria-label="Permalink to &quot;4. Timing filter (soft — feeds the score)&quot;">​</a></h2><p>These never override a hard fail; they only tilt the score (how big, how soon):</p><ul><li>Price not in freefall: 15m return ≥ <strong>−20%</strong>.</li><li>Not top-blasting: price within <strong>3%</strong> of ATH plus stoch-RSI-style overextension on 5m candles → penalty. The bot enters <em>after</em> a retrace leg, not into a vertical.</li><li>Buy/sell imbalance from OHLCV volume: heavy net selling in the last 5m → penalty.</li><li>Volume ignition: last 5m candle ≥ <strong>3×</strong> the trailing-hour average → bonus.</li></ul><h2 id="_5-opportunity-score-0–100" tabindex="-1">5. Opportunity score (0–100) <a class="header-anchor" href="#_5-opportunity-score-0–100" aria-label="Permalink to &quot;5. Opportunity score (0–100)&quot;">​</a></h2><p>Weighted blend, drives sizing and queue priority:</p><table tabindex="0"><thead><tr><th>Component</th><th>Weight</th></tr></thead><tbody><tr><td>Fee/TVL momentum (30m vs 24h)</td><td>30%</td></tr><tr><td>Volume/TVL turnover</td><td>20%</td></tr><tr><td>Vetting softness (holder distribution quality, holder growth, maker diversity)</td><td>25%</td></tr><tr><td>Timing (§4)</td><td>15%</td></tr><tr><td>Pool structure (bin-step fit, fee tier vs competition)</td><td>10%</td></tr></tbody></table><p>GMGN trending bonuses (sustained +8, emerging +4, fading +3) and smart-money flow bonuses stack on top but are capped at <strong>+10 combined</strong>; heavy smart-money net selling (&gt; $5,000) applies a −8 penalty.</p><h2 id="_6-entry-execution" tabindex="-1">6. Entry execution <a class="header-anchor" href="#_6-entry-execution" aria-label="Permalink to &quot;6. Entry execution&quot;">​</a></h2><p>Default shape — one-sided SOL, <strong>BidAsk</strong>, below current price:</p><ol><li>Compute swing high/low from 5m OHLCV over the pool&#39;s life (max 24h lookback).</li><li>Range top = active bin. Range bottom = the <em>shallower</em> of: fib <strong>0.786</strong> retracement of the swing, or <strong>−50%</strong> from current price. Floor of <strong>−40%</strong> minimum depth — never a thin sliver. (The planner also derives a cap from the P0 crash threshold, so no bins are planned below where P0 would already have fired.)</li><li>Translate to bin IDs. A DLMM position account spans ≤ 69 bins; if the range needs more, split into at most <strong>2</strong> position accounts.</li><li><strong>Bin-array rent</strong> (~0.075 SOL per array, non-refundable when arrays are new): soft budget one array — shrink the range first. Hard budget two arrays (0.15 SOL) only when score ≥ <strong>80</strong>. The bot quotes actual uninitialized arrays on-chain; RPC quote failure falls back to the worst-case estimate (fail closed). Never more than two arrays.</li><li>Open with <code>StrategyType.BidAsk</code>, SOL side only (<code>totalXAmount = 0</code>).</li><li>Tx policy: active-bin liquidity slippage <strong>5%</strong> (≈5 bins at bin step 100 — the earlier 1% setting produced 100% of live open failures as <code>ExceededBinSlippageTolerance</code>). Priority fee auto from recent fees; a failed program simulation never resends the same tx; <strong>3</strong> network retries, then abandon and re-quote. On bin-slippage rejection the live path <strong>rebuilds</strong> the position rather than spamming the same bad transaction.</li><li><strong>Second tranche</strong>: for score ≥ <strong>85</strong>, an additional BidAsk pocket <em>below</em> the primary, sized at <strong>50%</strong> of the primary, down toward −70% (clamped by the P0 safety floor). Skipped on the micro sleeve, when the primary already fills the floor, or when slots/size floors block it. Tranches count toward max open positions.</li></ol><p><strong>Exit swap path:</strong> on close, the token side converts to SOL via the Meteora Zap SDK (Jupiter V6), with a lite-Jupiter fallback. Normal exits use <strong>50 bps</strong> swap slippage; P0 safety exits use <strong>1000 bps</strong> (speed over price).</p><h2 id="_7-the-p0–p5-exit-ladder" tabindex="-1">7. The P0–P5 exit ladder <a class="header-anchor" href="#_7-the-p0–p5-exit-ladder" aria-label="Permalink to &quot;7. The P0–P5 exit ladder&quot;">​</a></h2><p>Each open position is polled every <strong>15s</strong>. Rules are checked in strict priority order — <strong>first match wins</strong>:</p><table tabindex="0"><thead><tr><th>Priority</th><th>Name</th><th>Trigger</th><th>Action</th></tr></thead><tbody><tr><td><strong>P0</strong></td><td>Safety exit</td><td>Any of: pool TVL −40% in 10 min · single wallet sells &gt;3% of supply in one tx · tracked insider cluster distributing · new whale &gt;10% · metadata changed or RugCheck flips to Danger · price −60% from entry (<strong>at any age</strong> — there is deliberately no time window)</td><td>Remove 100% + close immediately, market-dump token→SOL at 10% slippage, <strong>blacklist token + creator</strong>, log incident</td></tr><tr><td><strong>P1</strong></td><td>Stop loss</td><td>Mark-to-market in SOL (both sides + unclaimed fees) &lt; entry × <strong>0.75</strong></td><td>Close, swap token→SOL, realize loss, 24h re-entry cooldown. No conviction override — ever</td></tr><tr><td><strong>P2</strong></td><td>Rotation</td><td>Fee rate (30m annualized) &lt; 5%/day for 3 consecutive polls, or 30m volume &lt; $5,000; or position age &gt; 48h (then it stays only if it would qualify as a <em>fresh</em> entry today)</td><td>Close — dead weight; capital rotates to the queue</td></tr><tr><td><strong>P3</strong></td><td>Above range</td><td>Price &gt; range top by 5%, sustained</td><td>Close via zap, recover rent, record PnL. See win vs missed below</td></tr><tr><td><strong>P4</strong></td><td>In range</td><td>Earning</td><td>Claim/bank fees; escape hatch; profit lock (below)</td></tr><tr><td><strong>P5</strong></td><td>Below range</td><td>Price under the bottom bin — position is 100% token</td><td>Hold <strong>15 min</strong> grace (wick tolerance), then close, swap all token→SOL, realize the loss, 24h cooldown. Coinciding safety signal escalates to P0</td></tr></tbody></table><h3 id="p3-win-vs-missed" tabindex="-1">P3: win vs missed <a class="header-anchor" href="#p3-win-vs-missed" aria-label="Permalink to &quot;P3: win vs missed&quot;">​</a></h3><p>Two cases that look the same but mean opposite things:</p><ul><li><strong>Win</strong> — price dipped <em>into</em> the range, then recovered above it. Every bin it climbed back through sold our tokens above acquisition price; the position ends ~100% SOL with round-trip profit + fees. Exit after <strong>10 min</strong> sustained above range (short, so follow mode can arm).</li><li><strong>Missed</strong> — price pumped without ever entering the range. The SOL was never touched: no profit, no loss, just idle capital. Exit after <strong>45 min</strong> sustained (a shorter timer was churning ~0.002 SOL rent per round trip on slots the bot wasn&#39;t refilling).</li></ul><h3 id="re-entry-after-p3-anti-chasing" tabindex="-1">Re-entry after P3 (anti-chasing) <a class="header-anchor" href="#re-entry-after-p3-anti-chasing" aria-label="Permalink to &quot;Re-entry after P3 (anti-chasing)&quot;">​</a></h3><ul><li>The token goes back through the <strong>full pipeline as a fresh candidate</strong> — including the timing filter — so re-entry happens after a retrace signal, never into a vertical pump.</li><li><strong>Ladder decay:</strong> each successive re-entry on the same token within 24h sizes at <strong>0.75×</strong> the previous; max <strong>2</strong> re-entries. A re-entry must still clear a 0.2 SOL viability floor.</li><li><strong>Rate limits:</strong> ≤ 2 rebalances per position per 6h; skip entirely if projected rent + tx cost &gt; 25% of fees earned so far.</li><li><strong>House-money rule is off</strong> (it banked notional profit with no release path; deployable only ever fell).</li></ul><h3 id="p3-f-follow-mode" tabindex="-1">P3-F: Follow mode <a class="header-anchor" href="#p3-f-follow-mode" aria-label="Permalink to &quot;P3-F: Follow mode&quot;">​</a></h3><p>Optional overtime after any P3 close (win or missed), designed <strong>not</strong> to chase — the gate set below was the only configuration at/above breakeven in simulation over the recorded post-exit price paths:</p><ul><li>A P3 close on a main position <strong>arms a chain</strong>.</li><li>A leg opens only when <strong>all</strong> hold: pool 30m volume ≥ <strong>$100,000</strong> (4× the normal entry floor) · current 30m <strong>and</strong> 1h fee rates annualized ≥ the 24h gate (bypassing the stale 24h average) · price retraced <strong>15%</strong> from the post-exit/post-high peak · fresh token vetting passes.</li><li>Leg shape: one-sided SOL BidAsk, <strong>30%</strong> deep (tighter than the 40% default), top at current price, escape hatch disabled.</li><li><strong>Up-only:</strong> after a leg closes up-and-out, the chain re-arms only once price makes a <strong>new chain high</strong>. This condition alone separated +EV from −EV in the sim.</li><li>Chain ends on: any non-P3 leg close · <strong>3</strong> legs · cumulative chain PnL ≤ <strong>−0.075 SOL</strong> · 3 consecutive polls under the normal volume floor · <strong>12h</strong> age · blacklist or vet fail. A failed leg open cools the chain 300s.</li><li>Legs are fixed at <strong>0.25 SOL</strong>, exempt from the re-entry ladder, and excluded from the main Kelly ledger — the mode must earn bigger sizing with its own closed-leg evidence.</li><li>While a chain is live, the normal pipeline skips that token: one owner of re-entry timing per token.</li></ul><h2 id="_8-p4-detail-fees-escape-hatch-profit-lock" tabindex="-1">8. P4 detail: fees, escape hatch, profit lock <a class="header-anchor" href="#_8-p4-detail-fees-escape-hatch-profit-lock" aria-label="Permalink to &quot;8. P4 detail: fees, escape hatch, profit lock&quot;">​</a></h2><ul><li><strong>Claim</strong> when unclaimed fees ≥ max(0.05 SOL, 20× estimated tx cost), or every 4h, whichever first. When price first drops below range, fees are claimed immediately (min 0.005 SOL) so token-side fees convert to SOL at the top of a dump, not the bottom.</li><li><strong>Fee destination <code>bank</code>:</strong> token-side fees swap to SOL at claim time and bank to the wallet. (A <code>compound</code> mode exists in config for pools scoring ≥ 70 but banking is the shipped behavior; majors also bank only.)</li><li><strong>Escape hatch:</strong> if price fell through &gt; <strong>60%</strong> of the range depth and then recovers to the upper <strong>25%</strong> of the range → close and re-enter. This realizes fees and resets near the average acquisition price instead of round-tripping the whole dip. Disabled on follow legs and majors.</li><li><strong>Profit lock:</strong> if mark-to-market ≥ entry × <strong>1.30</strong> while still in range → withdraw <strong>30%</strong> of liquidity (position stays open and earning) and zap it to SOL. Fires at most <strong>once</strong> per position. A floor under strong runners without giving up the fee stream.</li></ul><h2 id="_9-majors-sleeve-separate-playbook" tabindex="-1">9. Majors sleeve (separate playbook) <a class="header-anchor" href="#_9-majors-sleeve-separate-playbook" aria-label="Permalink to &quot;9. Majors sleeve (separate playbook)&quot;">​</a></h2><p>SOL-quoted majors/alts on a symbol allowlist (<code>PUMP</code>, <code>ANSEM</code>, <code>JTO</code>, <code>BONK</code>, <code>WIF</code>, <code>RAY</code>, <code>JUP</code>), discovered by their own sweep. Key differences from meme:</p><table tabindex="0"><thead><tr><th>Aspect</th><th>Majors behavior</th></tr></thead><tbody><tr><td>Shape</td><td><strong>Spot</strong> (uniform bins), 12% below / 6% above price — SOL biased to the downside</td></tr><tr><td>Timing entry</td><td>RSI(14) ≤ 45, <strong>or</strong> price in the bottom 40% of the 24h swing; never above 75% of the swing</td></tr><tr><td>Size</td><td>Fixed 0.75 SOL, max 1.5 SOL per position, max <strong>1</strong> slot, ≤40% of wallet</td></tr><tr><td>Stop loss</td><td>entry × <strong>0.60</strong> (wider than meme — spot holds inventory)</td></tr><tr><td>Below-range grace</td><td><strong>120 min</strong> (vs meme 15)</td></tr><tr><td>Escape hatch / profit lock</td><td>Off — majors hold through dips</td></tr><tr><td>Rotation</td><td>Much slower: 20 consecutive polls under a 0.05%/day fee floor; max age 168h; above-range sustains 240/480 min</td></tr><tr><td>Fees</td><td>Bank only, claim min 0.02 SOL</td></tr></tbody></table><p>Majors run after meme entries and only when ≥ 2 slots stay free for memes. Token age must be ≥ 7 days.</p><h2 id="_10-blacklist-skip-rules" tabindex="-1">10. Blacklist &amp; skip rules <a class="header-anchor" href="#_10-blacklist-skip-rules" aria-label="Permalink to &quot;10. Blacklist &amp; skip rules&quot;">​</a></h2><p>Kept in the <code>blacklist</code> table with reason + expiry:</p><table tabindex="0"><thead><tr><th>Kind</th><th>What lands there</th></tr></thead><tbody><tr><td><strong>Permanent</strong></td><td>Creators with any rug in history; tokens that triggered P0; Token-2022 with transfer-fee/hook extensions</td></tr><tr><td><strong>24h cooldown</strong></td><td>Copycat losers of symbol dedupe; tokens that hard-failed vetting; tokens exited at a loss</td></tr><tr><td><strong>Structural skips</strong> (never candidates, not blacklisted)</td><td>Base fee &gt; 5% pools; non-SOL quotes (incl. SOL-USDC); pools where our position would exceed 20% of TVL</td></tr></tbody></table><p>Every skip is logged with the failing gate in the <code>decisions</code> table — the tuning dataset. Skipped candidates get outcome backfill (did the ones we passed on moon or rug?) so gates can be tightened or loosened with evidence, not vibes.</p><h2 id="_11-accounting" tabindex="-1">11. Accounting <a class="header-anchor" href="#_11-accounting" aria-label="Permalink to &quot;11. Accounting&quot;">​</a></h2><ul><li><strong>SOL is the unit of account</strong> (USD stored as a snapshot column for readability).</li><li>Per position: fees claimed + fees unclaimed + (exit value − entry value) − rent − tx costs, all in SOL. Realized PnL is <strong>measured wallet delta</strong> — what actually left and returned — never our own intent.</li><li><strong>Reconciliation:</strong> on startup, the chain wins. The bot enumerates the wallet&#39;s actual DLMM positions, diffs against the DB, repairs, and logs discrepancies.</li></ul><p class="cta-row"><a class="doc-btn ghost" href="./how-it-works">How it works</a><a class="doc-btn ghost" href="./risk">Risk &amp; sizing</a><a class="doc-btn ghost" href="./configuration">Configuration</a><a class="doc-btn ghost" href="https://github.com/CryptoGnome/dlmmbot/blob/main/STRATEGY.md" target="_blank" rel="noreferrer">STRATEGY.md</a></p>',49)])])}const u=t(a,[["render",s]]);export{p as __pageData,u as default};
